import { Component } from '@angular/core';

@Component({
  selector: 'app-nav-menu',
  templateUrl: './nav-menu.component.html',
  styleUrls: ['./nav-menu.component.css']
})
export class NavMenuComponent {
  isExpanded = false;

  collapse() {
    this.isExpanded = false;
  }

  toggle() {
    this.isExpanded = !this.isExpanded;
  }
}
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>PriceFlow - Stock Market Dashboard</title>
  <link href="https://cdn.jsdelivr.net/npm/bootstrap@4.5.2/dist/css/bootstrap.min.css" rel="stylesheet">
  <link href="https://cdn.jsdelivr.net/npm/tailwindcss@2.2.19/dist/tailwind.min.css" rel="stylesheet">
  <style>
    /* Custom styles for background and language toggle */
    .background-overlay {
      background-image: url('background.jpg');
      background-size: cover;
      background-position: center;
      background-attachment: fixed;
    }

    .language-switch {
      position: relative;
      display: inline-block;
      width: 60px;
      height: 34px;
    }

      .language-switch input {
        opacity: 0;
        width: 0;
        height: 0;
      }

    .language-slider {
      position: absolute;
      cursor: pointer;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background-color: #ccc;
      transition: 0.4s;
      border-radius: 34px;
    }

      .language-slider:before {
        position: absolute;
        content: "";
        height: 26px;
        width: 26px;
        left: 4px;
        bottom: 4px;
        background-color: white;
        transition: 0.4s;
        border-radius: 50%;
        background-size: contain;
        background-repeat: no-repeat;
      }

    input:checked + .language-slider {
      background-color: #1e3a8a; /* Dark blue to match navbar */
    }

      input:checked + .language-slider:before {
        transform: translateX(26px);
      }
      /* Flag images */
      input:checked + .language-slider:before {
        background-image: url('https://flagcdn.com/w20/mk.png'); /* Macedonian flag */
      }

    input:not(:checked) + .language-slider:before {
      background-image: url('https://flagcdn.com/w20/gb.png'); /* English flag */
    }
  </style>
</head>
<body class="background-overlay">
  <!-- Header Navigation -->
  <header>
    <nav class="navbar navbar-expand-sm navbar-light bg-blue-900 border-bottom box-shadow mb-3 text-white">
      <div class="container">
        <!-- Logo and App Name -->
        <a class="navbar-brand text-white" [routerLink]="['/']">
          <img src="logo.png" alt="PriceFlow Logo" class="h-8 mr-2">PriceFlowApp
        </a>
        <button class="navbar-toggler"
                type="button"
                data-toggle="collapse"
                data-target=".navbar-collapse"
                aria-label="Toggle navigation"
                [attr.aria-expanded]="isExpanded"
                (click)="toggle()">
          <span class="navbar-toggler-icon"></span>
        </button>
        <div class="navbar-collapse collapse d-sm-inline-flex justify-content-end"
             [ngClass]="{ show: isExpanded }">
          <ul class="navbar-nav flex-grow">
            <li class="nav-item"
                [routerLinkActive]="['link-active']"
                [routerLinkActiveOptions]="{ exact: true }">
              <a class="nav-link text-white" [routerLink]="['/']">Home</a>
            </li>
            <li class="nav-item" [routerLinkActive]="['link-active']">
              <a class="nav-link text-white" [routerLink]="['/counter']">Counter</a>
            </li>
            <li class="nav-item" [routerLinkActive]="['link-active']">
              <a class="nav-link text-white" [routerLink]="['/fetch-data']">Fetch data</a>
            </li>
          </ul>
          <!-- Language Toggle -->
          <div class="ml-3">
            <label class="language-switch">
              <input type="checkbox" id="languageToggle">
              <span class="language-slider"></span>
            </label>
          </div>
          <!-- Login Button -->
          <button onclick="openLoginModal()" class="ml-3 bg-blue-700 px-4 py-2 rounded-md hover:bg-blue-600 transition duration-300 text-white">
            LOGIN
          </button>
        </div>
      </div>
    </nav>
  </header>

  <!-- Main Content (Hero Section) -->
  <main class="min-h-screen flex items-center justify-center text-white">
    <div class="text-center">
      <h1 class="text-5xl font-bold mb-4">Welcome to PriceFlow</h1>
      <p class="text-xl mb-8">Track and analyze stock market trends with real-time insights.</p>
      <button onclick="openLoginModal()" class="bg-blue-600 px-8 py-3 rounded-md hover:bg-blue-700 transition duration-300">
        Get Started
      </button>
    </div>
  </main>

  <!-- Login Modal -->
  <div id="loginModal" class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center hidden z-50">
    <div class="bg-white p-6 rounded-lg shadow-xl w-full max-w-md mx-4">
      <div class="flex justify-between items-center mb-4">
        <h2 class="text-2xl font-bold text-gray-800">LOGIN</h2>
        <button onclick="closeLoginModal()" class="text-gray-500 hover:text-gray-700">
          <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"></path>
          </svg>
        </button>
      </div>
      <form class="space-y-4">
        <div>
          <label class="block text-sm font-medium text-gray-700 mb-1">Email</label>
          <input type="email" placeholder="Enter your email" class="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500">
        </div>
        <div>
          <label class="block text-sm font-medium text-gray-700 mb-1">Password</label>
          <input type="password" placeholder="Enter your password" class="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500">
        </div>
        <button type="submit" class="w-full bg-blue-500 text-white py-2 rounded-md hover:bg-blue-600 transition duration-300">
          Log In
        </button>
      </form>
      <div class="mt-4 text-center">
        <a href="#" class="text-blue-500 text-sm hover:underline">Forgot password?</a>
      </div>
      <div class="mt-4 text-center text-sm text-gray-600">
        Don't have an account? <a href="#" class="text-blue-500 hover:underline">Sign up</a>
      </div>
    </div>
  </div>

  <script src="https://code.jquery.com/jquery-3.5.1.slim.min.js"></script>
  <script src="https://cdn.jsdelivr.net/npm/bootstrap@4.5.2/dist/js/bootstrap.bundle.min.js"></script>
  <script>
        // Angular-specific bindings are placeholders; implement in Angular component
        let isExpanded = false;
        function toggle() {
            isExpanded = !isExpanded;
        }

        function openLoginModal() {
            document.getElementById('loginModal').classList.remove('hidden');
        }

        function closeLoginModal() {
            document.getElementById('loginModal').classList.add('hidden');
        }

        // Close modal on outside click
        document.getElementById('loginModal').addEventListener('click', function(e) {
            if (e.target === this) {
                closeLoginModal();
            }
        });

        // Language toggle functionality (placeholder)
        const langToggle = document.getElementById('languageToggle');
        langToggle.addEventListener('change', function() {
            // Add language switch logic here (e.g., update text content)
            console.log('Language toggled to:', this.checked ? 'Macedonian' : 'English');
        });
  </script>
</body>
</html>
